-- VPod (Cool Comforts Co., hervpod.com): four cooling gel pod products
-- (Everyday Comfort single + 3-pack, Postpartum & Menopause Comfort / Elite
-- single + 3-pack). Catalog entries only — VPod is NOT an ayna brand partner.
-- Extracted from a regenerated supabase/seed/product_catalog.sql
-- (`npm run catalog:export`); just the 4 VPod rows, safe to run standalone.
-- Idempotent: safe to re-run.

insert into public.product_catalog (id, name, brand, category, product_type, summary, price, image, url, tags, health_functions, where_to_buy, where_to_buy_in_stock, safety, doctor_opinion, community_review, effectiveness, clinician_opinion_source, clinician_attribution, source, internal, requires_prescription, user_rating, is_active, extra)
values
  ('p-vpod-everyday-comfort-single', 'VPod Everyday Comfort Single Pack', 'VPod', 'intimate-care', 'physical', 'A reusable, drug-free cooling gel pod you freeze and place in your underwear for up to 20 minutes of relief from external vulvar and vaginal itching, burning, dryness, irritation, or swelling. The curved, flexible pod has a 100% medical-grade silicone exterior that stays in place without adhesive. VPod markets it for yeast infections, BV, allergies, perimenopause and menopause, pregnancy and postpartum, and after sex or workouts; it eases symptoms but doesn’t treat their cause. One pod per pack.', '$19.99 (1 pod)', '/products/vpod/everyday-comfort-single.webp', 'https://hervpod.com/products/vpod-regular-single-pack', '["discomfort","comfort","menopause","postpartum","external-only","reusable","hormone-free"]'::jsonb, '["vaginal-health","comfort"]'::jsonb, '["hervpod.com","Amazon","Walmart"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Registered with the FDA as an over-the-counter medical product, per hervpod.com. FDA registration means the company and product are listed with the FDA; it is not FDA clearance or approval.","materials":"Each pod is 3 in long x 2.5 in wide, with a 100% medical-grade silicone exterior and a flexible gel interior (the gel itself isn''t disclosed). Hypoallergenic, odor-free, and sterile when packaged. Made in China for Cool Comforts Co. (Cincinnati, OH).","recalls":"No recalls are mentioned on hervpod.com; check current FDA and manufacturer recall notices.","sideEffects":"Cold can feel too intense on sensitive skin, so VPod says to test the temperature first and limit each use to 20 minutes. Full warnings are listed below.","opinionAlerts":"hervpod.com contradicts itself on reuse: the product page says single-use and \"Do not reuse,\" but its FAQ and full instructions say the pod is reusable for up to 30 days with cleaning. ayna follows the detailed instructions; check the package insert."}'::jsonb, 'Cold therapy is a standard, low-risk way to ease vulvar and perineal soreness: ACOG recommends an ice pack or cold gel pack on the perineal area for 10 to 20 minutes at a time after birth, and a Cochrane review found cooling may reduce perineal pain in the first days postpartum (low-certainty evidence). VPod packages that idea as a curved silicone pod that stays in place in underwear.

Cooling only eases symptoms. It doesn''t treat yeast infections, BV, allergies, or menopause-related dryness, so it should be used alongside the right treatment, not instead of it. See a doctor for itching or burning that doesn''t go away, unusual discharge, or odor. VPod says it was developed with gynecologists; no study of VPod itself was found.', 'hervpod.com shows 6 customer reviews for this pod, all 5 stars; reviewers describe instant, mess-free relief while waiting for yeast-infection treatment to work, and one wished extra covers were easier to order. These are reviews on the brand’s own site. Amazon and Walmart listings are linked below; both block automated access, so ayna hasn’t pulled their ratings.', 'Cold therapy has category-level support for easing perineal pain (Cochrane; ACOG). No independent study of VPod was found, and cooling relieves symptoms only, not their underlying cause.', 'independent', 'ayna synthesis of ACOG guidance and a Cochrane review; not a direct clinician quote. Product details are from hervpod.com.', 'curated', false, false, null, true, '{"faqUrl":"https://hervpod.com/pages/faq","doctorOpinionShort":"Cold packs are an ACOG-recommended way to ease perineal soreness, and a Cochrane review found cooling may reduce postpartum perineal pain. VPod relieves symptoms but doesn''t treat their cause. No study of VPod itself was found.","whoItsFor":["Short-term relief from external vulvar itching, burning, swelling, or soreness","Discomfort from a yeast infection or BV while treatment starts working","Perimenopause and menopause discomfort, and irritation after sex, workouts, or on hot days","Anyone who wants drug-free, mess-free relief instead of creams or padsicles"],"howToUse":{"intro":"Per VPod''s full instructions:","steps":["Put the unopened foil pack in the freezer for at least 1 hour, until the pod feels stiff.","Take it out and let it rest 3 to 5 minutes, then wash your hands and open the pack.","Touch the pod gently to your vulva first to check the temperature is comfortable.","Place it between the inner and outer labia (labia minora and majora), or in the center crotch of your underwear.","Wear it for up to 20 minutes, up to 3 times a day, waiting at least 10 minutes between uses.","After each use, rinse with warm water, wash with mild soap, and air dry; wipe with 70% isopropyl alcohol at least daily. Replace the pod after 30 days or if damaged."],"sourceUrl":"https://hervpod.com/pages/usage-instructions","sourceLabel":"hervpod.com: Instructions for Use"},"warnings":["External use only. Do not insert into the vagina or anus, and do not ingest.","For temporary symptom relief only; it does not treat yeast infections, BV, or other conditions. See a doctor for itching or burning that doesn’t go away, unusual discharge, or odor.","Remove before urinating, and don’t flush it.","Don’t use with other silicone-based products.","If the pod ruptures, clean the skin and throw the pod away (the gel may be slippery)."],"ingredients":"Medical-grade silicone exterior with a gel interior (gel not disclosed). Drug-free; no active ingredients.","scientificCitations":[{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8094618/","text":"Local cooling for relieving pain from perineal trauma sustained during childbirth (Cochrane review, 2020)","summary":"A Cochrane review of 10 randomized trials (1,233 women) found that cooling with an ice pack or cold gel pad may reduce perineal pain in the first two days after birth, but the evidence is low to very low certainty. This is evidence for cold therapy in general, not for VPod specifically."},{"url":"https://www.acog.org/womens-health/faqs/postpartum-pain-management","text":"ACOG: Postpartum Pain Management","summary":"ACOG recommends applying an ice pack or cold gel pack to the perineal area for 10 to 20 minutes at a time to relieve discomfort after birth. This is clinical guidance for cold therapy as a category, not validation of a specific product."},{"url":"https://www.acog.org/womens-health/faqs/vulvovaginal-health","text":"ACOG: Vulvovaginal Health","summary":"ACOG suggests cold packs for perineal pain and advises seeing an ob-gyn for itching, burning, or swelling that doesn’t go away, since yeast infections, BV, and other causes need their own treatment. Cooling eases symptoms but doesn’t treat the cause."}],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[{"platform":"amazon","url":"https://www.amazon.com/dp/B0F9YXP4MR","text":"Amazon: VPod Reusable Feminine Cooling Gel Pods, 1 Count","summary":"This pod’s Amazon listing, with customer ratings and reviews. Amazon blocks automated access, so no rating is quoted here; read the reviews directly."},{"platform":"walmart","url":"https://www.walmart.com/ip/Vpod-Single-Pack/17868111516","text":"Walmart: VPod Single Pack","summary":"This pod’s Walmart listing, with customer reviews. The site blocks automated access, so no rating is quoted here; read the reviews directly."},{"platform":"website","url":"https://hervpod.com/products/vpod-regular-single-pack","text":"hervpod.com: VPod Everyday Comfort Single Pack","summary":"VPod’s own product page, which shows 6 customer reviews, all 5 stars."}]}},"integrations":[],"badges":[],"isEmergingBrand":false}'::jsonb),
  ('p-vpod-everyday-comfort-3-pack', 'VPod Everyday Comfort 3 Pack', 'VPod', 'intimate-care', 'physical', 'A reusable, drug-free cooling gel pod you freeze and place in your underwear for up to 20 minutes of relief from external vulvar and vaginal itching, burning, dryness, irritation, or swelling. The curved, flexible pod has a 100% medical-grade silicone exterior that stays in place without adhesive. VPod markets it for yeast infections, BV, allergies, perimenopause and menopause, pregnancy and postpartum, and after sex or workouts; it eases symptoms but doesn’t treat their cause. Three pods per pack.', '$53.99 (3 pods)', '/products/vpod/everyday-comfort-3-pack.webp', 'https://hervpod.com/products/vpod-regular-multipack', '["discomfort","comfort","menopause","postpartum","external-only","reusable","hormone-free","cost"]'::jsonb, '["vaginal-health","comfort"]'::jsonb, '["hervpod.com","Walmart"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Registered with the FDA as an over-the-counter medical product, per hervpod.com. FDA registration means the company and product are listed with the FDA; it is not FDA clearance or approval.","materials":"Each pod is 3 in long x 2.5 in wide, with a 100% medical-grade silicone exterior and a flexible gel interior (the gel itself isn''t disclosed). Hypoallergenic, odor-free, and sterile when packaged. Made in China for Cool Comforts Co. (Cincinnati, OH).","recalls":"No recalls are mentioned on hervpod.com; check current FDA and manufacturer recall notices.","sideEffects":"Cold can feel too intense on sensitive skin, so VPod says to test the temperature first and limit each use to 20 minutes. Full warnings are listed below.","opinionAlerts":"hervpod.com contradicts itself on reuse: the product page says single-use and \"Do not reuse,\" but its FAQ and full instructions say the pod is reusable for up to 30 days with cleaning. ayna follows the detailed instructions; check the package insert."}'::jsonb, 'Cold therapy is a standard, low-risk way 